alter table public.feature_catalog add column if not exists configuration jsonb not null default '{}'::jsonb; insert into public.feature_catalog(feature_code,name,category,minimum_tier,enabled,configuration) values ('business_custom_notifications','Custom Business Notifications','business','business',true,'{"channels":["in_app","push"],"audience_scopes":["user","nearby","followers","business"],"source":"capability_gate"}'::jsonb) on conflict(feature_code) do update set name=excluded.name,category=excluded.category,minimum_tier=excluded.minimum_tier,enabled=true,configuration=excluded.configuration,updated_at=now(); create or replace function public.business_can_manage(p_business_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.is_platform_owner_session() or exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin','manager')); $$; create or replace function public.business_send_custom_notification(p_business_id uuid,p_event_type text,p_title text,p_body text,p_audience_scope text default 'business',p_payload jsonb default '{}'::jsonb,p_expires_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'not authorized'; end if; if not exists(select 1 from public.feature_catalog where feature_code='business_custom_notifications' and enabled) then raise exception 'capability unavailable'; end if; if p_audience_scope not in ('user','nearby','followers','business') then raise exception 'invalid audience scope'; end if; insert into public.notification_events(event_type,actor_user_id,audience_scope,payload,expires_at) values(p_event_type,auth.uid(),p_audience_scope,jsonb_build_object('business_id',p_business_id,'title',p_title,'body',p_body)||coalesce(p_payload,'{}'::jsonb),p_expires_at) returning id into v_id; return v_id; end $$; revoke all on function public.business_send_custom_notification(uuid,text,text,text,text,jsonb,timestamptz) from public; grant execute on function public.business_send_custom_notification(uuid,text,text,text,text,jsonb,timestamptz) to authenticated; revoke execute on function public.business_send_custom_notification(uuid,text,text,text,text,jsonb,timestamptz) from anon;
